using Servicio.RetazoMarket.Business.DTOs.ProductoMaterial;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;
namespace Servicio.RetazoMarket.Business.Services;
public class ProductoMaterialService:IProductoMaterialService {private readonly IProductoMaterialDataService _data;private readonly IProductoDataService _productos;private readonly IMaterialDataService _materiales;public ProductoMaterialService(IProductoMaterialDataService data,IProductoDataService productos,IMaterialDataService materiales)=>(_data,_productos,_materiales)=(data,productos,materiales);public async Task<ProductoMaterialResponse?> ObtenerAsync(int p,int m,CancellationToken ct=default){var x=await _data.ObtenerAsync(p,m,ct);return x is null?null:ProductoMaterialBusinessMapper.ToResponse(x);}public async Task<IReadOnlyList<ProductoMaterialResponse>> ObtenerPorProductoAsync(int p,CancellationToken ct=default)=>(await _data.ObtenerPorProductoAsync(p,ct)).Select(ProductoMaterialBusinessMapper.ToResponse).ToList();public async Task<ProductoMaterialResponse> CrearAsync(CrearProductoMaterialRequest r,CancellationToken ct=default){var e=ProductoMaterialValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await ValidarRelaciones(r.id_producto,r.id_material,r.es_personalizable,ct);if(await _data.ExisteAsync(r.id_producto,r.id_material,ct))throw new ValidationException("El material ya forma parte de la receta.");return ProductoMaterialBusinessMapper.ToResponse(await _data.CrearAsync(ProductoMaterialBusinessMapper.ToDataModel(r),ct));}public async Task<ProductoMaterialResponse?> ActualizarAsync(ActualizarProductoMaterialRequest r,CancellationToken ct=default){var e=ProductoMaterialValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await ValidarRelaciones(r.id_producto,r.id_material,r.es_personalizable,ct);var x=await _data.ActualizarAsync(ProductoMaterialBusinessMapper.ToDataModel(r),ct);return x is null?null:ProductoMaterialBusinessMapper.ToResponse(x);}private async Task ValidarRelaciones(int p,int m,string indicador,CancellationToken ct){var producto=await _productos.ObtenerPorIdAsync(p,ct)??throw new ValidationException("El producto no existe.");var material=await _materiales.ObtenerPorIdAsync(m,ct);if(material is null||material.mat_estado!="ACT")throw new ValidationException("El material no existe o está inactivo.");if(indicador.Trim().ToUpperInvariant()=="S"&&producto.es_personalizable!="S")throw new ValidationException("Un material personalizable requiere que el producto también sea personalizable.");}}
